import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = len(local_opt_tour)
    updated = edge_distance.copy()

    # Build set of undirected edges in the current tour (smaller index first)
    tour_edges = set()
    for k in range(n):
        u = local_opt_tour[k]
        v = local_opt_tour[(k + 1) % n]
        if u < v:
            tour_edges.add((u, v))
        else:
            tour_edges.add((v, u))

    max_usage = np.max(edge_n_used)
    if max_usage == 0:
        max_usage = 1  # avoid division by zero

    alpha = 0.2   # multiplicative penalty for tour edges
    beta = 0.1    # multiplicative reward for non-tour edges

    for i in range(n):
        for j in range(i + 1, n):
            usage = edge_n_used[i, j]
            base = edge_distance[i, j]
            if (i, j) in tour_edges:
                factor = 1.0 + alpha * (1.0 + usage)
            else:
                factor = 1.0 - beta * (1.0 - usage / max_usage)
                if factor < 0.01:
                    factor = 0.01
            updated[i, j] = base * factor
            updated[j, i] = updated[i, j]

    return updated

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    updated = edge_distance.copy()

    tour_edges = set()
    for k in range(n):
        u = local_opt_tour[k]
        v = local_opt_tour[(k + 1) % n]
        if u < v:
            tour_edges.add((u, v))
        else:
            tour_edges.add((v, u))

    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in tour_edges:
                delta = np.random.uniform(0, 0.1)   # constant additive noise
                updated[i, j] = updated[i, j] + delta
            else:
                delta = np.random.uniform(0, 0.05)  # constant subtractive noise
                updated[i, j] = max(1e-6, updated[i, j] - delta)
            updated[j, i] = updated[i, j]

    return updated
